        "file": "mttr.sql",
        "lang": "sql",
        "kind": "neutral",
        "code": "-- Every finding reported by the scanners ends up in a table like this one\nCREATE TABLE vulnerabilities (\n  id INTEGER PRIMARY KEY,\n  severity TEXT NOT NULL,\n  found_on TEXT NOT NULL, -- day the scanner reported it\n  fixed_on TEXT           -- NULL while the flaw is still open\n);\n\nINSERT INTO vulnerabilities (severity, found_on, fixed_on) VALUES\n  ('CRITICAL', '2026-03-01', '2026-03-02'),\n  ('CRITICAL', '2026-03-10', '2026-03-13'),\n  ('HIGH',     '2026-03-03', '2026-03-10'),\n  ('HIGH',     '2026-03-12', '2026-03-21'),\n  ('HIGH',     '2026-03-20', NULL),\n  ('MEDIUM',   '2026-02-15', '2026-03-17'),\n  ('MEDIUM',   '2026-03-18', NULL);\n\n-- Mean time to remediate (MTTR) and open backlog, per severity\nSELECT\n  severity,\n  COUNT(fixed_on) AS fixed,\n  COUNT(*) - COUNT(fixed_on) AS still_open,\n  ROUND(AVG(julianday(fixed_on) - julianday(found_on)), 1) AS mttr_days\nFROM vulnerabilities\nGROUP BY severity\nORDER BY CASE severity WHEN 'CRITICAL' THEN 1 WHEN 'HIGH' THEN 2 ELSE 3 END;\n",
        "output": "severity | fixed | still_open | mttr_days\nCRITICAL | 2     | 0          | 2.0\nHIGH     | 2     | 1          | 8.0\nMEDIUM   | 1     | 1          | 30.0\n",
        "note": {
          "fr": "`julianday()` convertit une date en nombre de jours : la soustraction donne le délai de correction. Les failles critiques sont corrigées en 2 jours en moyenne, les moyennes en 30 : c'est normal de traiter le plus grave d'abord, à condition que le stock ouvert ne grossisse pas.",
          "en": "`julianday()` converts a date into a number of days: the subtraction gives the time to fix. Critical flaws are fixed in 2 days on average, medium ones in 30: handling the worst first is normal, as long as the open backlog does not grow."
        }
